bounded_host_request.command:
set -eu
check=$(docker exec ai-core-model-gate sh -c 'printf "%s" "$AI_CORE_API_KEY"')
test "${#check}" -ge 16
out=$(printf '%s' "$check" | docker exec -i astera-v8 node -e '
let key="";process.stdin.setEncoding("utf8");
process.stdin.on("data",s=>key+=s);
process.stdin.on("end",async()=>{
 try{
  const url="http://127.0.0.1:18181/v1/models";
  const res=await fetch(url,{headers:{Authorization:"Bearer "+key},signal:AbortSignal.timeout(8000)});
  key="";
  const data=await res.json();
  const pass=res.status===200&&Array.isArray(data.data)&&data.data.length===1;
  console.log(JSON.stringify({consumer:"astera-v8",transport:"actual_node_runtime",gate_port:18181,status:res.status,model_count:data.data?.length,pass}));
  if(!pass)process.exitCode=3;
 }catch(e){console.log(JSON.stringify({consumer:"astera-v8",result:"TRANSPORT_ERROR",kind:e.name}));process.exitCode=4;}
});
')
unset check
gh api -X POST repos/seigo-gace/ai-core/issues/1/comments -f body="AI_CORE_SECOND_CONSUMER_ASTERA_GATE_AUTH $out KEY_EXPORTED=NO PRODUCT_SOURCE_CHANGED=NO" --jq '.html_url' >/dev/null
echo AI_CORE_ASTERA_GATE_AUTH=RECORDED
